css:
[data-workspace-area="conversation"] {
  background:
    linear-gradient(180deg, rgba(5,8,20,0.5) 0%, rgba(5,8,20,0.3) 40%, rgba(5,8,20,0.6) 100%),
    var(--theme-background-image) center / cover no-repeat fixed !important;
}
.messages-timeline-scroll { background: transparent !important; }
[data-chat-header] {
  background: rgba(6,9,22,0.55) !important;
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
}
[data-slot="composer-host"] {
  background: rgba(8,13,30,0.72) !important;
  backdrop-filter: blur(18px) saturate(150%);
  -webkit-backdrop-filter: blur(18px) saturate(150%);
  border-color: rgba(46,230,166,0.22) !important;
  box-shadow: 0 0 0 1px rgba(46,230,166,0.06), 0 12px 40px -12px rgba(46,230,166,0.25);
}
[data-user-message-bubble] {
  background: rgba(18,35,58,0.7) !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(120,170,255,0.14) !important;
}
.chat-markdown { text-shadow: 0 1px 2px rgba(0,0,0,0.55); }
.chat-markdown-codeblock {
  background: rgba(8,13,30,0.82) !important;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
::-webkit-scrollbar-thumb { background: rgba(46,230,166,0.25); border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: rgba(46,230,166,0.45); }
[data-slot="scroll-area-thumb"] { background: rgba(46,230,166,0.3) !important; }
